// services/apiService.js
import axios from 'axios';

const BASE_URL = 'http://assistant.psy-kokh.online:3000';

const apiService = {
    // Функція для входу користувача
    loginUser: (email, password) => {
        return axios.post(`${BASE_URL}/api/v1/psychologist_sessions`, {
            email: email,
            password: password
        });
    },

    //Функція для завантаження  даних профілю
    async getUserProfile(token) {
        const config = {
            headers: { 'authtoken': token },
        };
        try {
            const response = await axios.get(`${BASE_URL}/api/v1/psychologist_profile/profile`, config);
            return response.data;
        } catch (error) {
            console.error('Під час отримання даних сталася помилка: ', error);
        }
    },

    //Функція для відображення всіх клієнтів
    getClients: (token) => {
        return axios.get(`${BASE_URL}/api/v1/clients`, {
            headers: { 'authtoken': token }
        });
    },

    //Функція для введення шаблону
    createCustomForm: (token, title, primaryPollId) => {
        const config = {
            headers: { 'authtoken': token }
        };
        const formData = {
            title: title,
            primary_poll_id: primaryPollId,
            // Припустимо, що форма для відправлення може бути представлена як JSON-об'єкт
            // Якщо у вас є інші дані для відправлення, ви можете додати їх сюди
        };
        return axios.post(`${BASE_URL}/api/v1/custom_forms`, formData, config);
    },
};

export default apiService;
